-- Documentos fiscais: vídeo do MDF-e, logo depois do CT-e (o de NCM/CEST passa para o fim)
UPDATE lessons l JOIN modules m ON m.module_id = l.module_id SET l.position = 5 WHERE m.system_id = 'fiscal' AND m.name = 'Documentos fiscais' AND l.youtube_id = 'fbEJ1H0U1ts';
INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'MDF-e: o que é e quais são as obrigatoriedades do manifesto eletrônico', 'O que é o MDF-e (Manifesto Eletrônico de Documentos Fiscais), quem precisa emitir e quais informações ele leva. Vídeo do canal Bsoft.', '7:36', '2020-06-15', 4, 'admin', 'youtube', '_KM_C_xmxNI', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fiscal' AND m.name = 'Documentos fiscais' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = '_KM_C_xmxNI')
